(()=>{'use strict';
const R=RF,$=(s,e=document)=>e.querySelector(s),$$=(s,e=document)=>[...e.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fac=id=>R.facilities.find(f=>f.id===id),usr=id=>R.users.find(u=>u.id===id);
const fmt=d=>new Date(d).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const days=d=>d?Math.floor((R.NOW-new Date(d))/864e5):null;
const mask=n=>n.split(' ').map(w=>w[0]+'•••').join(' ');
const IC={home:'M3 11l9-8 9 8v9a1 1 0 01-1 1h-5v-6H9v6H4a1 1 0 01-1-1z',plus:'M12 5v14M5 12h14',list:'M4 6h16M4 12h16M4 18h10',inbox:'M3 13l3-8h12l3 8v6H3zM3 13h5l1 3h6l1-3h5',dir:'M12 21s7-6.2 7-12a7 7 0 10-14 0c0 5.8 7 12 7 12zM12 11a2 2 0 100-4 2 2 0 000 4',chart:'M4 20V10M10 20V4M16 20v-7M22 20H2',lock:'M6 11V8a6 6 0 1112 0v3M5 11h14v10H5z',users:'M16 20v-2a4 4 0 00-4-4H7a4 4 0 00-4 4v2M9.5 10a3.5 3.5 0 100-7 3.5 3.5 0 000 7M21 20v-2a4 4 0 00-3-3.9','shield':'M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z',bell:'M6 9a6 6 0 0112 0c0 6 2 7 2 7H4s2-1 2-7M10 20h4',gear:'M12 15a3 3 0 100-6 3 3 0 000 6M19 12l2-1-2-4-2 1a7 7 0 00-2-1l-.5-2h-4L10 7a7 7 0 00-2 1L6 7l-2 4 2 1a7 7 0 000 2l-2 1 2 4 2-1a7 7 0 002 1l.5 2h4l.5-2a7 7 0 002-1l2 1 2-4-2-1z',clock:'M12 7v5l3 2M12 21a9 9 0 100-18 9 9 0 000 18'};
const ic=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${IC[n]}"/></svg>`;
const LOGO=`<svg viewBox="0 0 40 40" aria-hidden="true"><rect width="40" height="40" rx="11" fill="var(--brand)"/><circle cx="11" cy="20" r="4" fill="var(--on-brand)"/><circle cx="29" cy="20" r="4" fill="none" stroke="var(--on-brand)" stroke-width="3"/><path d="M15 20h10M29 24c0 7-18 7-18-2" fill="none" stroke="var(--on-brand)" stroke-width="2.5" stroke-linecap="round"/></svg>`;
const S={user:null,offline:false,revealed:{},audit:R.audit.map(a=>a.slice()),referrals:JSON.parse(JSON.stringify(R.referrals)),outbox:[],wiz:null,mfaPending:null,sessionLeft:900,seq:1};
try{S.theme=localStorage.getItem('rf-theme')||''}catch(e){S.theme=''}
if(S.theme)document.documentElement.dataset.theme=S.theme;
const NAV={clinician:[['home','Home','home'],['new','New referral','plus'],['referrals','My referrals','list'],['directory','Directory','dir'],['access','Access log','lock']],
coordinator:[['inbox','Inbox','inbox'],['referrals','Referrals','list'],['directory','Directory','dir'],['dashboard','Dashboard','chart'],['access','Access log','lock']],
manager:[['dashboard','Dashboard','chart'],['referrals','Referrals','list'],['directory','Directory','dir'],['access','Access log','lock']],
admin:[['admin/users','Users & roles','users'],['admin/facilities','Facilities','dir'],['admin/audit','Audit explorer','shield'],['admin/retention','Retention','clock'],['dashboard','Dashboard','chart']]};
const MOBILE={clinician:['home','new','referrals','directory','settings'],coordinator:['inbox','referrals','directory','dashboard','settings'],manager:['dashboard','referrals','directory','access','settings'],admin:['admin/users','admin/audit','admin/retention','dashboard','settings']};
const pill=(s)=>{const m={Created:'p-mute',Sent:'p-info',Received:'p-info',Accepted:'p-ok',Scheduled:'p-ok','Patient attended':'p-brand',Completed:'p-ok',Declined:'p-bad',Cancelled:'p-warn',Queued:'p-warn'};return `<span class="pill ${m[s]||'p-mute'}">${esc(s)}</span>`};
const prio=p=>`<span class="pill prio-${p} ${p==='Emergency'?'p-bad':p==='Urgent'?'p-warn':'p-mute'}">${p}</span>`;
function ver(f){const d=days(f.ver.at);if(d===null)return{c:'p-bad',t:'Unverified',s:'No verification on record. Call before referring.',lvl:3};if(d>30)return{c:'p-bad',t:'Stale: verified '+d+' days ago',s:'Confirm by phone before referring.',lvl:3};if(d>7)return{c:'p-warn',t:'Verification due ('+d+' days)',s:'Re-verification requested.',lvl:2};return{c:'p-ok',t:'Verified '+(d===0?'today':d+' day'+(d>1?'s':'')+' ago'),s:'',lvl:1}}
const me=()=>S.user,myFac=()=>me().fac;
const live=m=>{$('#live').textContent=m};
function toast(m){live(m);const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=m;document.body.append(t);setTimeout(()=>t.remove(),3200)}
function log(action,obj,reason='—',flag='—'){S.audit.unshift([new Date().toISOString().slice(0,16).replace('T',' '),me().name.replace(' (synthetic)',''),action,obj,reason,flag])}
function dlg(html,onOpen){const d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.addEventListener('close',()=>d.remove());d.addEventListener('click',e=>{if(e.target.dataset.close!==undefined)d.close()});d.showModal();onOpen&&onOpen(d);return d}
const go=h=>{location.hash=h};
const route=()=>{const h=location.hash.replace(/^#\/?/,'')||'';const p=h.split('/');return{path:h,p}};
function party(r){return me().fac===r.from||me().fac===r.to}
function visible(){const f=myFac();return S.referrals.filter(r=>me().role==='manager'||me().role==='admin'?true:r.from===f||r.to===f)}
function inboxCount(){return S.referrals.filter(r=>r.to===myFac()&&['Sent','Received'].includes(r.status)).length}

/* ---------- shell ---------- */
function shell(title,body){const u=me(),nav=NAV[u.role],mob=MOBILE[u.role];const cur=route().path;
const all=Object.fromEntries(nav.map(n=>[n[0],n]));all.settings=['settings','Settings','gear'];
const link=n=>{const on=cur===n[0]||cur.startsWith(n[0]+'/')&&n[0]!=='home';const cnt=n[0]==='inbox'?inboxCount():0;return `<a href="#/${n[0]}" ${on?'aria-current="page"':''}>${ic(n[2])}<span>${n[1]}</span>${cnt?`<span class="badge-n" aria-label="${cnt} awaiting">${cnt}</span>`:''}</a>`};
const tab=k=>{const n=all[k]||['settings','Settings','gear'];const on=cur===n[0]||cur.startsWith(n[0]+'/');return `<a href="#/${n[0]}" class="${k==='new'?'fab':''}" ${on?'aria-current="page"':''}>${ic(n[2])}<span>${n[1].replace('My referrals','Referrals').replace('New referral','New').replace('Users & roles','Users').replace('Audit explorer','Audit')}</span></a>`};
return `<div class="demo">Synthetic demonstration data. Simulated design prototype: no real patients, no live integrations.</div>
<div class="shell"><aside class="side"><a class="brand" href="#/">${LOGO}ReferralFlow</a><nav class="nav" aria-label="Main">${nav.map(link).join('')}${link(['notifications','Notifications','bell'])}${link(['settings','Settings','gear'])}</nav>
<div style="margin-top:auto" class="mute"><small>${esc(u.name)}<br>${esc(u.roleLabel)} · ${esc(fac(u.fac).name)}</small></div></aside>
<div><main id="main" class="main" tabindex="-1">
<div class="top"><div class="mobilebar" style="margin:0">${LOGO.replace('<svg','<svg style="width:30px;height:30px"')}<b style="font-family:var(--font-display);font-size:1.15rem;margin-left:8px">ReferralFlow</b></div>
<div class="sess"><span class="pill ${S.offline?'p-warn':'p-ok'}">${S.offline?'Offline':'Online'}</span><span class="pill p-brand">MFA verified</span><span id="sessclock">Session ${Math.ceil(S.sessionLeft/60)} min</span></div></div>
${S.offline?`<div class="banner warn" role="status"><b>You are offline.</b><span>New referrals are saved encrypted on this device and sent when the connection returns. Nothing is lost.</span></div>`:''}
${body}</main></div></div>
<nav class="tabs" aria-label="Main">${mob.map(tab).join('')}</nav>`}

/* ---------- views ---------- */
function V_login(){const m=S.mfaPending;
if(m)return `<div class="login"><div class="brand">${LOGO}ReferralFlow</div><div class="card"><h1>Enter your code</h1><p>Open your authenticator app and enter the 6-digit code. MFA is required for everyone.</p><form id="mfa" novalidate><div class="field"><label for="otp">6-digit code</label><input id="otp" inputmode="numeric" autocomplete="one-time-code" maxlength="6" aria-describedby="otperr"><div class="hint">Prototype: enter any 6 digits.</div><div id="otperr" class="err" role="alert"></div></div><button class="btn" style="width:100%">Verify and sign in</button></form><p class="mute" style="margin-top:14px"><a href="#/login" data-act="cancelmfa">Use a different account</a></p></div></div>`;
return `<div class="demo">Synthetic demonstration data. Simulated design prototype.</div><div class="login"><div class="brand">${LOGO}ReferralFlow</div>
${S.msg?`<div class="banner info" role="status">${esc(S.msg)}</div>`:''}
<div class="card"><h1>Sign in</h1><p class="mute">Referrals, with the patient kept private.</p><form id="login" novalidate>
<div class="field"><label for="acct">Demo account (role)</label><select id="acct">${R.users.filter(u=>u.mfa).map(u=>`<option value="${u.id}">${esc(u.roleLabel)}: ${esc(u.name)}</option>`).join('')}</select></div>
<div class="field"><label for="pw">Password</label><input id="pw" type="password" autocomplete="current-password" aria-describedby="pwerr"><div class="hint">Prototype: type anything with 8+ characters.</div><div id="pwerr" class="err" role="alert"></div></div>
<button class="btn" style="width:100%">Continue</button></form></div>
<p class="mute" style="text-align:center;font-size:.85rem">Patient details are hidden by default. Every reveal is logged.</p></div>`}

function V_home(){const f=myFac();const mine=visible();const attn=mine.filter(r=>r.from===f&&(['Declined'].includes(r.status)||r.info||r.status==='Completed'));
return `<h1>Good morning, Amina</h1><p class="mute">${esc(fac(f).name)}</p>
<a class="btn" style="width:100%;min-height:64px;font-size:1.15rem" href="#/new">${ic('plus')} New referral</a><p class="hint" style="margin-bottom:22px">Takes under 2 minutes. Only what the receiving team needs.</p>
${S.outbox.length?`<div class="banner warn"><div><b>${S.outbox.length} referral${S.outbox.length>1?'s':''} waiting to send</b><br><span>Saved on this device. ${S.offline?'Will send when you are online.':'Ready to send.'}</span></div><button class="btn sm quiet" data-act="sync" ${S.offline?'disabled':''}>Sync now</button></div>`:''}
<div class="card"><h2>Needs your attention</h2>${attn.length?`<ul class="list">${attn.map(rrow).join('')}</ul>`:'<p class="mute">Nothing waiting. Well done.</p>'}</div>
<div class="card"><h2>Recent referrals</h2><ul class="list">${mine.filter(r=>r.from===f).slice(0,5).map(rrow).join('')}</ul><p style="margin:10px 0 0"><a href="#/referrals">See all</a></p></div>`}
function rrow(r){const p=R.patients[r.p];const sub=r.from===myFac()?'To '+fac(r.to).name:'From '+fac(r.from).name;const att=r.info?'<span class="pill p-warn">Info requested</span>':'';
return `<li><a class="row" href="#/referral/${r.id}"><div class="grow"><div class="t"><span class="masked" title="Masked">${mask(p.name)}</span> · ${esc(r.reason.length>46?r.reason.slice(0,44)+'…':r.reason)}</div><small>${sub} · ${fmt(r.created)} · ref ${r.id}</small></div><div style="display:grid;gap:4px;justify-items:end">${prio(r.prio)}${pill(r.status)}${att}</div></a></li>`}

function V_referrals(){const q=(S.fq||'').toLowerCase(),st=S.fs||'';let l=visible().filter(r=>(!st||r.status===st)&&(!q||(r.reason+r.id).toLowerCase().includes(q)));
return `<h1>Referrals</h1><div class="card"><div class="grid g3" style="align-items:end"><div class="field" style="margin:0"><label for="fq">Search reason or referral ID</label><input id="fq" value="${esc(S.fq||'')}" placeholder="e.g. malaria or r-7f3a"><div class="hint">Patient names are not searchable here.</div></div>
<div class="field" style="margin:0"><label for="fs">Status</label><select id="fs"><option value="">All statuses</option>${[...R.STATUSES,'Declined','Cancelled'].map(s=>`<option ${s===st?'selected':''}>${s}</option>`).join('')}</select></div>
<form id="lookup" class="field" style="margin:0"><label for="lk">Open by referral ID</label><div style="display:flex;gap:8px"><input id="lk" placeholder="r-91de"><button class="btn quiet">Open</button></div></form></div></div>
<div class="card">${l.length?`<ul class="list">${l.map(rrow).join('')}</ul>`:`<div style="text-align:center;padding:28px"><h3>No referrals match</h3><p class="mute">Try clearing the filters.</p><button class="btn sec" data-act="clearf">Clear filters</button></div>`}</div>`}

function stepsBar(n){return `<div class="steps" aria-hidden="true">${[1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`}
function V_new(){const w=S.wiz||(S.wiz={step:1,start:Date.now(),pid:'',prio:'Routine',reason:'',share:true,dest:'',consent:'',confirm:false,err:{}});
const el=Math.max(1,Math.round((Date.now()-w.start)/1000));const hd=`<div class="mobilebar" style="justify-content:space-between"><a href="#/home">Cancel</a><span class="mute" id="wtimer">Step ${w.step} of 4</span></div>${stepsBar(w.step)}`;
const E=k=>w.err[k]?`<div class="err" role="alert" id="e-${k}">${w.err[k]}</div>`:'';
const draft=`<p class="hint">${S.offline?'Offline: draft saved on this device (encrypted).':'Draft saved automatically.'}</p>`;
if(w.step===1){const opts=Object.entries(R.patients);return `${hd}<h1>Who is the patient?</h1><p class="mute">Choose from your facility's synthetic patient list. Only name, sex and age are shared by default.</p>
<div class="field"><label>Patient</label><div role="radiogroup" aria-label="Patient">${opts.map(([k,p])=>`<label class="opt"><input type="radio" name="pid" value="${k}" ${w.pid===k?'checked':''}><span><b>${esc(p.name)}</b> <small>${p.sex}, ${p.age} yrs · ${p.id}</small></span></label>`).join('')}</div>${E('pid')}</div>${draft}
<div class="sticky-act"><button class="btn" data-act="next" style="flex:1">Continue</button></div>`}
if(w.step===2)return `${hd}<h1>Why are you referring?</h1>
<div class="field"><label>Priority</label><div class="seg">${['Routine','Urgent','Emergency'].map(p=>`<label class="opt"><input type="radio" name="prio" value="${p}" ${w.prio===p?'checked':''}><span><b>${p}</b><div class="hint">${{Routine:'Within weeks',Urgent:'Within 24 hours',Emergency:'Now. Call ahead.'}[p]}</div></span></label>`).join('')}</div></div>
<div class="field"><label for="reason">Reason for referral</label><textarea id="reason" maxlength="240" aria-describedby="e-reason" ${w.err.reason?'aria-invalid="true"':''}>${esc(w.reason)}</textarea><div class="hint">One or two lines. ${w.reason.length}/240</div>${E('reason')}</div>
<div class="field"><label class="opt" style="margin:0"><input type="checkbox" id="share" ${w.share?'checked':''}><span><b>Include my clinical note</b><div class="hint">Encrypted. Visible only to the receiving team once accepted. Leave off if not needed.</div></span></label></div>${draft}
<div class="sticky-act"><button class="btn quiet" data-act="back">Back</button><button class="btn" data-act="next" style="flex:1">Continue</button></div>`;
if(w.step===3){const l=R.facilities.filter(f=>f.id!==myFac()&&f.cap.some(c=>/in|Emergency|Maternity|ICU|CT|Ophth|Dialysis|Paed|Ortho/.test(c)));return `${hd}<h1>Where is the patient going?</h1><p class="mute">Availability shows when it was last checked and by whom.</p>
<div class="field" role="radiogroup" aria-label="Receiving facility">${l.map(f=>{const v=ver(f);return `<label class="opt"><input type="radio" name="dest" value="${f.id}" ${w.dest===f.id?'checked':''}><span style="flex:1"><b>${esc(f.name)}</b><div class="hint">${esc(f.type)} · ${f.cap.slice(0,3).join(', ')}</div><span class="pill ${v.c}" style="margin-top:6px">${v.t}</span>${v.lvl>1?`<div class="hint"><b>${v.s}</b></div>`:''}</span></label>`}).join('')}${E('dest')}</div>${draft}
<div class="sticky-act"><button class="btn quiet" data-act="back">Back</button><button class="btn" data-act="next" style="flex:1">Continue</button></div>`}
const p=R.patients[w.pid],f=fac(w.dest);
return `${hd}<h1>Consent and send</h1>
<div class="card"><h3>What will be shared</h3><ul style="margin:0;padding-left:20px"><li>Name, sex, age: <b>${esc(p.name)}, ${p.sex}, ${p.age}</b></li><li>Priority and reason: ${w.prio}, ${esc(w.reason)}</li><li>Clinical note: <b>${w.share?'included (encrypted)':'not included'}</b></li><li>To: ${esc(f.name)}</li></ul><p class="hint" style="margin:8px 0 0">Not shared: address, ID numbers, contacts, insurance.</p></div>
<div class="field"><label>Patient consent</label><div role="radiogroup" aria-label="Consent">${['Verbal consent recorded by clinician','Written consent on file','Guardian consent (verbal)','Emergency: patient unable to consent'].map(c=>`<label class="opt"><input type="radio" name="consent" value="${c}" ${w.consent===c?'checked':''}><span>${c}${c.startsWith('Emergency')?'<div class="hint">A reason is logged. Confirm applicable rules with counsel.</div>':''}</span></label>`).join('')}${E('consent')}</div>
<p class="hint">Time so far: <b id="elapsed">${Math.floor(el/60)}:${String(el%60).padStart(2,'0')}</b> (prototype timer)</p>
<div class="sticky-act"><button class="btn quiet" data-act="back">Back</button><button class="btn" data-act="send" style="flex:1">${S.offline?'Save to outbox':'Send referral'}</button></div>`}

function V_done(){const d=S.done;return `<div style="text-align:center;padding:30px 0"><div class="pill p-ok" style="margin-bottom:12px">${d.queued?'Saved on device':'Sent'}</div><h1>${d.queued?'Saved. Will send when online.':'Referral sent'}</h1><p>Reference <b>${d.id}</b> · ${d.to}</p><p class="mute">Created in ${d.time}. You will be told when it is received.</p><div style="display:grid;gap:10px;max-width:340px;margin:20px auto"><a class="btn" href="#/${d.queued?'home':'referral/'+d.id}">${d.queued?'Back to home':'Track this referral'}</a><a class="btn sec" href="#/new">Create another</a></div></div>`}

function tracker(r){const idx=R.STATUSES.indexOf(r.status);const term=['Declined','Cancelled'].includes(r.status);
const evs=r.ev.map(e=>e[0]);const lastOk=Math.max(...evs.map(e=>R.STATUSES.indexOf(e)));
return `<ol class="track" aria-label="Referral progress">${R.STATUSES.map((s,i)=>{let c='';if(term){c=i<=lastOk?'done':''}else c=i<idx?'done':i===idx?'cur':'';return `<li class="${c}" ${c==='cur'?'aria-current="step"':''}><i></i>${s}</li>`}).join('')}</ol>${term?`<div class="banner ${r.status==='Declined'?'bad':'warn'}" style="margin-top:10px"><div><b>${r.status}: ${esc(r.reasonCode)}</b>${r.reasonText?'<br>'+esc(r.reasonText):''}</div></div>`:''}`}
function V_referral(id){const r=S.referrals.find(x=>x.id===id);if(!r)return `<h1>Not found</h1><p>No referral with that ID.</p><a href="#/referrals">Back</a>`;
const p=R.patients[r.p],isTo=r.to===myFac(),isFrom=r.from===myFac();const u=me();
if(!party(r)&&!S.revealed['bg'+id]&&u.role!=='manager'&&u.role!=='admin')return `<p><a href="#/referrals">‹ Referrals</a></p><h1>Referral ${r.id}</h1><div class="banner bad"><div><b>You are not part of this referral.</b><br>Patient information is hidden. In a genuine emergency you can use break-glass access. A reason is required and the access is reviewed.</div></div><button class="btn danger" data-act="bg" data-id="${id}">Break-glass access</button>`;
if(u.role==='manager'||u.role==='admin'){if(!S.revealed['bg'+id]&&!party(r))return `<p><a href="#/referrals">‹ Referrals</a></p><h1>Referral ${r.id}</h1><p>${prio(r.prio)} ${pill(r.status)}</p>${tracker(r)}<div class="banner info"><div><b>Aggregate view.</b> Your role does not include patient details. Progress and reasons only.</div></div>`}
if(isTo&&r.status==='Sent'){r.status='Received';r.ev.push(['Received',R.NOW.toISOString(),'Receiving desk']);log('Received','Referral '+r.id)}
const rev=S.revealed[id]||S.revealed['bg'+id];const act=[];
if(isTo){if(r.status==='Received'){act.push(['accept','Accept','btn'],['decline','Decline','btn danger'],['info','Request info','btn quiet'])}if(r.status==='Accepted')act.push(['schedule','Schedule appointment','btn']);if(r.status==='Scheduled')act.push(['attended','Patient attended','btn'],['noshow','Did not attend','btn quiet']);if(r.status==='Patient attended')act.push(['counter','Send summary back','btn'])}
if(isFrom&&!['Completed','Declined','Cancelled','Patient attended'].includes(r.status))act.push(['cancel','Cancel referral','btn quiet']);
if(isFrom&&r.status==='Declined')act.push(['redirect','Refer elsewhere','btn']);
const tab=S.rt||'overview';
return `<p><a href="#/referrals">‹ Referrals</a></p><div class="top"><div><h1 style="margin:0">Referral ${r.id}</h1><div class="chip-row" style="margin-top:6px">${prio(r.prio)}${pill(r.status)}</div></div></div>
<div class="banner ${/Emergency/.test(r.consent)?'warn':'ok'}"><div><b>Consent:</b> ${esc(r.consent)}<br><small>Recorded ${fmt(r.created)} by ${esc(r.ev[0][2])}</small></div></div>
${S.revealed['bg'+id]?'<div class="banner bad" role="status"><b>Break-glass access active.</b> Everything you view is logged and reviewed.</div>':''}
<div class="card">${tracker(r)}</div>
${act.length?`<div class="chip-row" style="margin-bottom:16px">${act.map(a=>`<button class="${a[2]}" data-act="r-${a[0]}" data-id="${id}">${a[1]}</button>`).join('')}</div>`:''}
<div class="tabsbar" role="tablist">${['overview','messages','history'].map(t=>`<button role="tab" aria-selected="${tab===t}" data-act="rt" data-t="${t}">${{overview:'Overview',messages:'Messages ('+r.msgs.length+')',history:'History'}[t]}</button>`).join('')}</div>
${tab==='overview'?`<div class="grid g2"><div class="card"><h3>Patient</h3><dl style="margin:0"><dt class="mute">Name</dt><dd style="margin:0 0 8px"><span class="masked">${rev?esc(p.name):mask(p.name)}</span></dd><dt class="mute">Sex, age</dt><dd style="margin:0 0 8px">${rev?p.sex+', '+p.age+' years':'•, ••'}</dd><dt class="mute">Patient ID</dt><dd style="margin:0 0 8px"><span class="masked">${rev?p.id:'SYN-P-••••'}</span> <small class="mute">(synthetic)</small></dd></dl>
${rev?`<button class="btn sm quiet" data-act="hide" data-id="${id}">Hide again</button>`:`<button class="btn sm sec" data-act="reveal" data-id="${id}">Reveal identifiers</button><p class="hint">Reveal is logged with your reason.</p>`}</div>
<div class="card"><h3>Referral</h3><p><b>From</b> ${esc(fac(r.from).name)}<br><b>To</b> ${esc(fac(r.to).name)}</p><p>${esc(r.reason)}</p>${r.appt?`<p><b>Appointment:</b> ${r.appt.replace('T',' ')}</p>`:''}</div></div>
<div class="card"><h3>Clinical note <span class="pill p-mute">Encrypted</span></h3>${rev&&(isTo&&['Accepted','Scheduled','Patient attended','Completed'].includes(r.status)||isFrom||S.revealed['bg'+id])?`<p>${esc(p.note)}</p>`:`<p class="mute">${isTo&&!['Accepted','Scheduled','Patient attended','Completed'].includes(r.status)?'Visible after you accept the referral.':'Hidden. Reveal identifiers to view if you are involved in care.'}</p>`}</div>
${r.counter?`<div class="card" style="border-color:var(--ok)"><h3>Counter-referral summary</h3><p>${esc(r.counter)}</p><small class="mute">Loop closed ${fmt(r.ev[r.ev.length-1][1])}</small></div>`:''}`:''}
${tab==='messages'?`<div class="card">${r.msgs.length?r.msgs.map(m=>`<div class="msg ${m[0]===fac(myFac()).name?'me':''}"><small>${esc(m[0])} · ${fmt(m[2])}</small>${esc(m[1])}</div>`).join(''):'<p class="mute">No messages yet.</p>'}
<form id="msgf" data-id="${id}" style="margin-top:12px"><label for="mt">Message</label><textarea id="mt" style="min-height:80px"></textarea><div class="hint">Do not include names or ID numbers. Use the referral reference.</div><div id="mterr" class="err" role="alert"></div><button class="btn" style="margin-top:8px">Send message</button></form></div>`:''}
${tab==='history'?`<div class="card"><ul class="tl">${r.ev.map(e=>`<li><b>${e[0]}</b><br><small class="mute">${fmt(e[1])} · ${esc(e[2])}</small></li>`).join('')}</ul></div>`:''}`}

function V_inbox(){const f=myFac();const order={Emergency:0,Urgent:1,Routine:2};const l=S.referrals.filter(r=>r.to===f&&['Sent','Received','Accepted','Scheduled','Patient attended'].includes(r.status)).sort((a,b)=>order[a.prio]-order[b.prio]);const tab=S.it||'new';
const sets={new:l.filter(r=>['Sent','Received'].includes(r.status)),active:l.filter(r=>['Accepted','Scheduled'].includes(r.status)),close:l.filter(r=>r.status==='Patient attended')};
return `<h1>Inbox</h1><p class="mute">${esc(fac(f).name)}. Emergencies first.</p>
<div class="grid g3" style="margin-bottom:16px">${[['new','Need a response'],['active','Accepted or scheduled'],['close','Awaiting summary']].map(([k,t])=>`<button class="stat" style="text-align:left;cursor:pointer;${tab===k?'border:2px solid var(--brand)':''}" data-act="it" data-t="${k}"><b>${sets[k].length}</b><span>${t}</span></button>`).join('')}</div>
<div class="card">${sets[tab].length?`<ul class="list">${sets[tab].map(rrow).join('')}</ul>`:`<div style="text-align:center;padding:28px"><h3>All clear</h3><p class="mute">Nothing in this list.</p></div>`}</div>`}

function V_directory(){const q=(S.dq||'').toLowerCase(),t=S.dt||'',v=S.dv||'';const l=R.facilities.filter(f=>(!q||(f.name+f.cap.join()).toLowerCase().includes(q))&&(!t||f.type===t)&&(!v||(v==='ok'?ver(f).lvl===1:ver(f).lvl>1)));
return `<h1>Facility directory</h1><div class="banner info"><div>Synthetic directory. In production, facility identity would link to the Kenya Master Facility List code; service availability is verified separately and timestamped here.</div></div>
<div class="card"><div class="grid g3" style="align-items:end"><div class="field" style="margin:0"><label for="dq">Search facility or service</label><input id="dq" value="${esc(S.dq||'')}" placeholder="e.g. dialysis"></div><div class="field" style="margin:0"><label for="dt">Type</label><select id="dt"><option value="">All types</option>${[...new Set(R.facilities.map(f=>f.type))].map(x=>`<option ${x===t?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin:0"><label for="dv">Verification</label><select id="dv"><option value="">Any</option><option value="ok" ${v==='ok'?'selected':''}>Recently verified</option><option value="stale" ${v==='stale'?'selected':''}>Due, stale or unverified</option></select></div></div></div>
<div class="card">${l.length?`<ul class="list">${l.map(f=>{const x=ver(f);return `<li><a class="row" href="#/facility/${f.id}"><div class="grow"><div class="t">${esc(f.name)}</div><small>${esc(f.type)} · KEPH ${f.keph} · ${esc(f.hours)}</small><div style="margin-top:4px"><small>${esc(f.cap.slice(0,4).join(' · '))}</small></div></div><span class="pill ${x.c}">${x.t}</span></a></li>`}).join('')}</ul>`:`<div style="text-align:center;padding:28px"><h3>No facilities match</h3><p class="mute">Try a different service or clear filters.</p></div>`}</div>`}
function V_facility(id){const f=fac(id);if(!f)return '<h1>Not found</h1>';const x=ver(f);
return `<p><a href="#/directory">‹ Directory</a></p><h1>${esc(f.name)}</h1><p class="mute">${esc(f.type)} · KEPH level ${f.keph} · ${esc(f.county)} · ${f.code} <small>(synthetic code)</small></p>
<div class="banner ${x.lvl===1?'ok':x.lvl===2?'warn':'bad'}"><div><b>${x.t}</b><br>Verified by: ${esc(f.ver.by)}${f.ver.at?' · '+fmt(f.ver.at):''}${x.s?'<br><b>'+x.s+'</b>':''}</div></div>
<div class="grid g2"><div class="card"><h3>Contact and hours</h3><p>${esc(f.hours)}<br><a href="tel:${f.phone.replace(/\s/g,'')}">${f.phone}</a><br>Ambulance: ${f.ambulance?'Yes':'No'}</p></div>
<div class="card"><h3>Referral capabilities</h3><p>Accepts referrals in: ${f.cap.some(c=>/in/.test(c))?'Yes':'Limited'}<br>Sends referrals out: ${f.cap.some(c=>/out/.test(c))?'Yes':'Receives only'}</p></div></div>
<div class="card"><h3>Services</h3><ul class="list">${f.cap.filter(c=>!/Referral/.test(c)).map(c=>`<li class="row" style="min-height:52px"><span class="grow">${esc(c)}</span><span class="pill ${x.lvl===1?'p-ok':x.lvl===2?'p-warn':'p-bad'}">${x.lvl===1?'Available':'Unconfirmed'}</span></li>`).join('')}</ul></div>
<button class="btn quiet" data-act="reportdir" data-id="${id}">Report a change</button> ${['coordinator','admin'].includes(me().role)&&me().fac===id||me().role==='admin'?`<button class="btn" data-act="verify" data-id="${id}">Mark verified now</button>`:''}`}

function bars(data,max,fmtv=v=>v){return data.map(([k,v])=>`<div style="display:grid;grid-template-columns:150px 1fr 44px;gap:10px;align-items:center;margin:8px 0"><span style="font-size:.9rem">${esc(k)}</span><div class="bar" role="img" aria-label="${esc(k)} ${v}"><i style="width:${v/max*100}%"></i></div><b>${fmtv(v)}</b></div>`).join('')}
function V_dashboard(){const w=R.weekly,mx=Math.max(...w.map(x=>x[1]));
const chart=`<svg viewBox="0 0 360 170" role="img" aria-label="Referrals created per week, weeks 5 to 10, rising from 31 to 48" style="width:100%;height:auto">${[0,1,2,3].map(i=>`<line x1="30" x2="350" y1="${20+i*40}" y2="${20+i*40}" stroke="var(--chart-grid)" stroke-opacity=".35"/>`).join('')}${w.map((d,i)=>{const h=d[1]/mx*120;return `<rect x="${44+i*52}" y="${140-h}" width="34" height="${h}" rx="5" fill="var(--chart-a)"/><text x="${61+i*52}" y="${134-h}" text-anchor="middle" font-size="12" fill="var(--ink)">${d[1]}</text><text x="${61+i*52}" y="160" text-anchor="middle" font-size="12" fill="var(--ink-2)">${d[0]}</text>`}).join('')}</svg>`;
return `<h1>Network dashboard</h1><div class="banner info"><div><b>Synthetic demonstration data.</b> Aggregates only. No patient information on this page.</div></div>
<div class="grid g4 keep2" style="margin-bottom:16px"><div class="stat"><b>48</b><span>Created this week</span></div><div class="stat"><b>17</b><span>Pending response</span></div><div class="stat"><b>3h 40m</b><span>Median time to accept</span></div><div class="stat"><b>22%</b><span>Incomplete (declined, cancelled, did not attend)</span></div></div>
<div class="grid g2"><div class="card"><h3>Referrals created per week</h3>${chart}</div><div class="card"><h3>Why referrals were not completed</h3>${bars(R.reasonsInc,12)}<p class="hint">Reasons are required for every incomplete referral.</p></div></div>
<div class="card"><h3>Facility comparison</h3><div class="banner warn"><div><b>Read with care.</b> Facilities differ in case mix, staffing and distance. Rates for fewer than 5 referrals are hidden. Use to find where support is needed, not to rank or blame.</div></div><div class="tw"><table class="stack"><thead><tr><th>Receiving facility</th><th>Referrals (n)</th><th>Median time to respond</th><th>Incomplete rate</th></tr></thead><tbody>${R.facStats.map(s=>`<tr><td class="fac" data-label="Receiving facility">${esc(s[0])}</td><td data-label="Referrals (n)">${s[1]}${s[1]<10?' <span class="pill p-warn">small n</span>':''}</td><td data-label="Median time to respond">${s[1]<5?'n&lt;5, hidden':s[2]}</td><td data-label="Incomplete rate">${s[3]===null?'n&lt;5, hidden':s[3]+'%'}</td></tr>`).join('')}</tbody></table></div>
<p style="margin:12px 0 0"><button class="btn sec sm" data-act="export">Export aggregate CSV</button></p></div>`}

function V_access(){const mine=me().role==='clinician';const rows=S.audit.filter(a=>!mine||a[1]===me().name.replace(' (synthetic)',''));
return `<h1>${mine?'My access log':'Access log'}</h1><p class="mute">${mine?'Everything you opened, revealed or changed.':'Who viewed or revealed patient information.'} Break-glass entries are flagged for review.</p>
<div class="card tw">${logTable(rows)}</div>`}
function logTable(rows){const H=['When','Who','Action','Record','Reason','Flag'];return `<table class="stack"><thead><tr>${H.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>`<tr ${a[2]==='Break-glass'?'class="alert"':''}>${[esc(a[0].replace('T',' ')),esc(a[1]),a[2]==='Break-glass'?'<b>Break-glass</b>':esc(a[2]),esc(a[3]),esc(a[4]),esc(a[5])].map((c,i)=>`<td data-label="${H[i]}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`}

function V_admin(sub){if(sub==='users')return `<div class="top"><h1 style="margin:0">Users and roles</h1><button class="btn" data-act="invite">Invite user</button></div><div class="card tw"><table><thead><tr><th>Name</th><th>Role</th><th>Facility</th><th>MFA</th><th>Last sign-in</th><th></th></tr></thead><tbody>${R.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${u.roleLabel}</td><td>${esc(fac(u.fac).name)}</td><td>${u.mfa?'<span class="pill p-ok">On</span>':'<span class="pill p-warn">Pending</span>'}</td><td>${u.last}</td><td><button class="btn sm quiet" data-act="editu" data-id="${u.id}">Edit</button></td></tr>`).join('')}</tbody></table></div><p class="hint">MFA cannot be turned off for any role.</p>`;
if(sub==='facilities')return `<div class="top"><h1 style="margin:0">Facilities</h1><button class="btn" data-act="regfac">Register facility</button></div><div class="card"><ul class="list">${R.facilities.map(f=>{const x=ver(f);return `<li><a class="row" href="#/facility/${f.id}"><div class="grow"><div class="t">${esc(f.name)}</div><small>${esc(f.type)} · ${f.code}</small></div><span class="pill ${x.c}">${x.t}</span></a></li>`}).join('')}</ul></div>`;
if(sub==='audit'){const q=(S.aq||'').toLowerCase(),a=S.aa||'';const rows=S.audit.filter(r=>(!a||r[2]===a)&&(!q||r.join(' ').toLowerCase().includes(q)));
return `<h1>Audit explorer</h1><div class="card"><div class="grid g3" style="align-items:end"><div class="field" style="margin:0"><label for="aq">Search</label><input id="aq" value="${esc(S.aq||'')}" placeholder="actor, record, reason"></div><div class="field" style="margin:0"><label for="aa">Action</label><select id="aa"><option value="">All</option>${[...new Set(S.audit.map(r=>r[2]))].map(x=>`<option ${x===a?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn sec" data-act="export">Export log</button></div></div><div class="card tw">${rows.length?logTable(rows):'<p class="mute">No entries match.</p>'}</div><p class="hint">Entries cannot be edited or deleted. Audit log retention is configured in Retention.</p>`}
return `<h1>Retention and security settings</h1><div class="banner warn"><div><b>Confirm with counsel.</b> Retention periods must be set from legal advice. Values here are placeholders, not recommendations.</div></div>
<form id="ret" class="card" novalidate>${[['Clinical notes (years)','ret1',10],['Referral records (years)','ret2',10],['Audit logs (years)','ret3',10],['Unsent device drafts (days)','ret4',7],['Idle session timeout (minutes)','ret5',15]].map(([l,i,v])=>`<div class="field"><label for="${i}">${l}</label><input id="${i}" type="number" min="1" value="${v}" aria-describedby="${i}e"><div class="err" id="${i}e" role="alert"></div></div>`).join('')}
<div class="field"><label class="opt"><input type="checkbox" checked disabled><span><b>MFA required for all users</b><div class="hint">Locked on.</div></span></label></div><button class="btn">Save settings</button></form>`}

function V_notifications(){return `<h1>Notification preview</h1><p class="mute">Notifications never contain patient names, IDs or clinical details. They only say something needs attention.</p><div class="card"><ul class="list">${R.notifs.map(n=>`<li class="row"><span class="grow"><b>${n[0]}</b><br><small>${n[1]}</small></span><small>${n[2]}</small></li>`).join('')}</ul></div>`}
function V_settings(){return `<h1>Settings</h1><div class="card"><h3>Appearance</h3><div class="seg"><button class="btn quiet" data-act="theme" data-t="light">Light</button><button class="btn quiet" data-act="theme" data-t="dark">Dark</button><button class="btn quiet" data-act="theme" data-t="">System</button></div></div>
<div class="card"><h3>Connection</h3><label class="opt"><input type="checkbox" id="offl" ${S.offline?'checked':''}><span><b>Simulate being offline</b><div class="hint">Try creating a referral while offline.</div></span></label></div>
<div class="card"><h3>Session</h3><p>You are signed in with MFA. Idle sessions end after 15 minutes with a 60-second warning.</p><button class="btn quiet" data-act="timeout">Simulate session timeout</button> <button class="btn quiet" data-act="notif">Notification preview</button></div>
<div class="card"><h3>Prototype states</h3><a href="#/states">View loading, empty and error states</a></div><button class="btn danger" data-act="logout">Sign out</button>`}
function V_states(){return `<p><a href="#/settings">‹ Settings</a></p><h1>States gallery</h1><div class="grid g2"><div class="card"><h3>Loading</h3><div class="sk"></div><div class="sk" style="width:70%"></div><div class="sk" style="width:85%"></div></div><div class="card"><h3>Empty</h3><div style="text-align:center;padding:16px"><b>No referrals yet</b><p class="mute">Start with a new referral.</p><a class="btn sec sm" href="#/new">New referral</a></div></div>
<div class="card"><h3>Error</h3><div class="banner bad" role="alert"><div><b>Could not load the directory.</b><br>Check your connection. Your work is saved.</div><button class="btn sm quiet">Retry</button></div></div><div class="card"><h3>Success</h3><div class="banner ok"><b>Referral sent.</b>&nbsp;Reference r-7f3a.</div></div>
<div class="card"><h3>Offline</h3><div class="banner warn"><b>Offline.</b>&nbsp;Saved on this device, will sync.</div></div><div class="card"><h3>Forbidden</h3><div class="banner bad"><div><b>You do not have access to this page.</b><br>Your role does not include it.</div></div></div></div>`}

/* ---------- render ---------- */
const TITLES={home:'Home',new:'New referral',referrals:'Referrals',inbox:'Inbox',directory:'Directory',dashboard:'Dashboard',access:'Access log',settings:'Settings',notifications:'Notifications'};
function render(){const app=$('#app'),{path,p}=route();
if(!S.user){document.title='ReferralFlow: Sign in';app.innerHTML=V_login();if(path!=='login'&&path!=='')history.replaceState(null,'','#/login');return bind()}
let body;const k=p[0];
if(k===''||k==='login'){const t={clinician:'home',coordinator:'inbox',manager:'dashboard',admin:'admin/users'}[me().role];return go('/'+t)}
const guard={inbox:['coordinator'],new:['clinician'],home:['clinician'],admin:['admin'],dashboard:['coordinator','manager','admin']};
if(guard[k]&&!guard[k].includes(me().role))body=`<h1>No access</h1><div class="banner bad"><div><b>You do not have access to this page.</b><br>Your role (${me().roleLabel}) does not include it.</div></div>`;
else if(k==='new'&&S.done&&S.doneShow){body=V_done()}
else body=({home:V_home,referrals:V_referrals,new:V_new,referral:()=>V_referral(p[1]),inbox:V_inbox,directory:V_directory,facility:()=>V_facility(p[1]),dashboard:V_dashboard,access:V_access,admin:()=>V_admin(p[1]||'users'),notifications:V_notifications,settings:V_settings,states:V_states}[k]||(()=>'<h1>Page not found</h1>'))();
document.title='ReferralFlow: '+(TITLES[k]||(k==='referral'?'Referral':k==='admin'?'Admin':k==='facility'?'Facility':'Page'));
app.innerHTML=shell('',body);if(k!=='new')S.doneShow=false;bind();window.scrollTo(0,0)}
function bind(){}
window.addEventListener('hashchange',render);

/* ---------- events ---------- */
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;
if(f.id==='login'){const pw=$('#pw').value;if(pw.length<8){$('#pwerr').textContent='Enter your password (8+ characters in this prototype).';$('#pw').setAttribute('aria-invalid','true');$('#pw').focus();return}S.mfaPending=$('#acct').value;S.msg='';return render()}
if(f.id==='mfa'){const v=$('#otp').value;if(!/^\d{6}$/.test(v)){$('#otperr').textContent='Enter the 6 digits from your authenticator app.';$('#otp').setAttribute('aria-invalid','true');return $('#otp').focus()}S.user=usr(S.mfaPending);S.mfaPending=null;S.sessionLeft=900;log('Login (MFA ok)','Session');go('/');return render()}
if(f.id==='lookup'){const v=$('#lk').value.trim();if(v)go('/referral/'+v);return}
if(f.id==='msgf'){const t=$('#mt').value.trim();if(!t){$('#mterr').textContent='Write a message first.';return $('#mt').focus()}const r=S.referrals.find(x=>x.id===f.dataset.id);r.msgs.push([fac(myFac()).name,t,R.NOW.toISOString()]);log('Message sent','Referral '+r.id);toast('Message sent');return render()}
if(f.id==='ret'){let bad=false;$$('#ret input[type=number]').forEach(i=>{const e=$('#'+i.id+'e');if(!(+i.value>=1)){e.textContent='Enter a number of 1 or more.';i.setAttribute('aria-invalid','true');bad=true}else{e.textContent='';i.removeAttribute('aria-invalid')}});if(!bad){log('Retention settings changed','Settings');toast('Settings saved (simulated)')}return}});
document.addEventListener('input',e=>{const t=e.target;
if(t.id==='fq'){S.fq=t.value;rerenderKeep('fq')}if(t.id==='dq'){S.dq=t.value;rerenderKeep('dq')}if(t.id==='aq'){S.aq=t.value;rerenderKeep('aq')}
if(t.id==='reason'&&S.wiz){S.wiz.reason=t.value;const h=t.parentElement.querySelector('.hint');if(h)h.textContent='One or two lines. '+t.value.length+'/240'}});
function rerenderKeep(id){const pos=$('#'+id).selectionStart;render();const e=$('#'+id);e.focus();e.setSelectionRange(pos,pos)}
document.addEventListener('change',e=>{const t=e.target,w=S.wiz;
if(t.id==='fs'){S.fs=t.value;render()}if(t.id==='dt'){S.dt=t.value;render()}if(t.id==='dv'){S.dv=t.value;render()}if(t.id==='aa'){S.aa=t.value;render()}
if(t.id==='offl'){S.offline=t.checked;toast(S.offline?'Offline simulated':'Back online');render()}
if(w){if(t.name==='pid')w.pid=t.value;if(t.name==='prio')w.prio=t.value;if(t.name==='dest')w.dest=t.value;if(t.name==='consent')w.consent=t.value;if(t.id==='share')w.share=t.checked}});
function stopSession(msg){S.user=null;S.msg=msg;S.wiz=null;go('/login');render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act,id=b.dataset.id,w=S.wiz;
const A={
rt(){S.rt=b.dataset.t;render()},it(){S.it=b.dataset.t;render()},clearf(){S.fq='';S.fs='';render()},
theme(){S.theme=b.dataset.t;document.documentElement.dataset.theme=S.theme||'';if(!S.theme)delete document.documentElement.dataset.theme;try{localStorage.setItem('rf-theme',S.theme)}catch(x){}},
logout(){stopSession('You have been signed out.')},
cancelmfa(){S.mfaPending=null;render()},
timeout(){timeoutDlg()},notif(){go('/notifications')},
export(){toast('Export prepared (simulated). Aggregates only; export is logged.');log('Export','Aggregate report')},
next(){const e={};if(w.step===1&&!w.pid)e.pid='Choose a patient to continue.';if(w.step===2&&w.reason.trim().length<5)e.reason='Write the reason for referral (at least a few words).';if(w.step===3&&!w.dest)e.dest='Choose a receiving facility.';w.err=e;if(Object.keys(e).length){render();const f=$('.err');f&&f.scrollIntoView({block:'center'});return live(Object.values(e)[0])}
if(w.step===3){const f=fac(w.dest),x=ver(f);if(x.lvl===3&&!w.confirm){return dlg(`<h2>This facility's information is out of date</h2><p>${esc(f.name)}: ${x.t}. Services may have changed. Call ${f.phone} to confirm before sending, or choose another facility.</p><div class="chip-row"><button class="btn" data-close data-act="stalego">I have confirmed by phone</button><button class="btn quiet" data-close>Choose another</button></div>`)}}
w.step++;render()},
stalego(){w.confirm=true;w.step++;render()},
back(){w.step--;render()},
send(){if(!w.consent){w.err.consent='Record how consent was given before sending.';render();return live(w.err.consent)}
const sec=Math.round((Date.now()-w.start)/1000),t=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');
const r={id:'r-'+Math.random().toString(16).slice(2,6),p:w.pid,from:myFac(),to:w.dest,prio:w.prio,reason:w.reason.trim(),status:S.offline?'Queued':'Sent',by:me().id,created:R.NOW.toISOString(),consent:w.consent,ev:[['Created',R.NOW.toISOString(),me().name.split(' (')[0]]],msgs:[]};
if(S.offline){S.outbox.push(r)}else{r.ev.push(['Sent',R.NOW.toISOString(),me().name.split(' (')[0]]);S.referrals.unshift(r)}
log(S.offline?'Referral queued offline':'Referral sent','Referral '+r.id,w.consent);S.done={id:r.id,to:fac(w.dest).name,time:t,queued:S.offline};S.doneShow=true;S.wiz=null;render()},
sync(){const n=S.outbox.length;b.textContent='Syncing…';setTimeout(()=>{S.outbox.forEach(r=>{r.status='Sent';r.ev.push(['Sent',R.NOW.toISOString(),'Sync']);S.referrals.unshift(r)});S.outbox=[];toast(n+' referral'+(n>1?'s':'')+' sent');render()},900)},
reveal(){dlg(`<h2>Reveal identifiers</h2><p>This is logged against your name. Only continue if you are involved in this patient's care.</p><form id="rv"><div class="field"><label for="rr">Reason</label><select id="rr"><option value="">Choose a reason</option><option>Confirming patient at the desk</option><option>Preparing for appointment</option><option>Clinical review</option></select><div id="rre" class="err" role="alert"></div></div><div class="chip-row"><button class="btn">Reveal and log</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#rv',d).onsubmit=ev=>{ev.preventDefault();const v=$('#rr',d).value;if(!v){$('#rre',d).textContent='Choose a reason to continue.';return $('#rr',d).focus()}S.revealed[id]=true;log('Reveal identifiers','Referral '+id,v,'Logged');d.close();toast('Revealed and logged');render()}})},
hide(){delete S.revealed[id];render()},
bg(){dlg(`<h2>Break-glass access</h2><div class="banner bad"><div>For genuine emergencies only. You are not part of this referral. Your access is logged and flagged for review by the facility lead.</div></div><form id="bgf"><div class="field"><label for="bgr">Reason (required)</label><textarea id="bgr" style="min-height:90px"></textarea><div id="bge" class="err" role="alert"></div></div><div class="chip-row"><button class="btn danger">Confirm break-glass</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#bgf',d).onsubmit=ev=>{ev.preventDefault();const v=$('#bgr',d).value.trim();if(v.length<10){$('#bge',d).textContent='Describe the emergency (at least 10 characters).';return $('#bgr',d).focus()}S.revealed['bg'+id]=true;log('Break-glass','Referral '+id,v,'Flagged for review');d.close();render()}})},
'r-accept'(){setSt(id,'Accepted');toast('Accepted. The referrer has been told.')},
'r-decline'(){reasonDlg(id,'Decline referral',R.declineReasons,'Declined')},
'r-cancel'(){reasonDlg(id,'Cancel referral',R.cancelReasons,'Cancelled')},
'r-noshow'(){reasonDlg(id,'Patient did not attend',['Patient could not be reached','Transport or cost barrier','Patient chose to be treated elsewhere','Other (add note)'],'Cancelled')},
'r-info'(){dlg(`<h2>Request information</h2><form id="inf"><div class="field"><label for="it">What do you need?</label><textarea id="it"></textarea><div id="ite" class="err" role="alert"></div></div><div class="chip-row"><button class="btn">Send request</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#inf',d).onsubmit=ev=>{ev.preventDefault();const v=$('#it',d).value.trim();if(!v){$('#ite',d).textContent='Say what information you need.';return $('#it',d).focus()}const r=S.referrals.find(x=>x.id===id);r.msgs.push([fac(myFac()).name,v,R.NOW.toISOString()]);r.info=true;d.close();toast('Request sent');S.rt='messages';render()}})},
'r-schedule'(){dlg(`<h2>Schedule appointment</h2><form id="sch"><div class="field"><label for="sd">Date and time</label><input id="sd" type="datetime-local"><div id="sde" class="err" role="alert"></div></div><div class="chip-row"><button class="btn">Confirm</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#sch',d).onsubmit=ev=>{ev.preventDefault();const v=$('#sd',d).value;if(!v){$('#sde',d).textContent='Pick a date and time.';return $('#sd',d).focus()}const r=S.referrals.find(x=>x.id===id);r.appt=v;d.close();setSt(id,'Scheduled');toast('Appointment scheduled')}})},
'r-attended'(){setSt(id,'Patient attended');toast('Marked as attended')},
'r-counter'(){dlg(`<h2>Send summary to referrer</h2><p class="hint">What was done and what happens next. No identifiers needed.</p><form id="cn"><div class="field"><label for="ct">Summary</label><textarea id="ct"></textarea><div id="cte" class="err" role="alert"></div></div><div class="chip-row"><button class="btn">Send and close loop</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#cn',d).onsubmit=ev=>{ev.preventDefault();const v=$('#ct',d).value.trim();if(v.length<10){$('#cte',d).textContent='Add a short summary for the referrer.';return $('#ct',d).focus()}S.referrals.find(x=>x.id===id).counter=v;d.close();setSt(id,'Completed');toast('Loop closed. Referrer notified.')}})},
'r-redirect'(){go('/directory');toast('Choose another facility, then create a new referral')},
invite(){dlg(`<h2>Invite user</h2><form id="iv" novalidate><div class="field"><label for="ie">Work email</label><input id="ie" type="email"><div id="iee" class="err" role="alert"></div></div><div class="field"><label for="ir">Role</label><select id="ir"><option>Clinician</option><option>Facility coordinator</option><option>Network manager</option></select></div><p class="hint">They must set up MFA before first use.</p><div class="chip-row"><button class="btn">Send invite</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#iv',d).onsubmit=ev=>{ev.preventDefault();if(!/^\S+@\S+\.\S+$/.test($('#ie',d).value)){$('#iee',d).textContent='Enter a valid email address.';return $('#ie',d).focus()}d.close();log('User invited','User','Role '+$('#ir',d).value);toast('Invite sent (simulated)')}})},
editu(){const u=usr(id);dlg(`<h2>${esc(u.name)}</h2><div class="field"><label for="er">Role</label><select id="er"><option>${u.roleLabel}</option><option>Clinician</option><option>Facility coordinator</option></select></div><div class="chip-row"><button class="btn" data-close data-act="saveu">Save role</button><button class="btn quiet" data-close data-act="resetmfa">Reset MFA</button><button class="btn danger" data-close data-act="suspend">Suspend</button></div>`)},
saveu(){log('Role changed','User','—');toast('Role saved (simulated)')},resetmfa(){log('MFA reset','User');toast('MFA reset. User must re-enrol.')},suspend(){log('User suspended','User');toast('User suspended (simulated)')},
regfac(){dlg(`<h2>Register facility</h2><form id="rf" novalidate><div class="field"><label for="fn">Facility name</label><input id="fn"><div id="fne" class="err" role="alert"></div></div><div class="field"><label for="fk">MFL code (verify against registry)</label><input id="fk" placeholder="e.g. 12345"></div><div class="chip-row"><button class="btn">Register</button><button type="button" class="btn quiet" data-close>Cancel</button></div></form>`,d=>{$('#rf',d).onsubmit=ev=>{ev.preventDefault();if(!$('#fn',d).value.trim()){$('#fne',d).textContent='Enter the facility name.';return $('#fn',d).focus()}d.close();toast('Registered as unverified (simulated)')}})},
reportdir(){toast('Change reported to the facility coordinator (simulated)')},
verify(){const f=fac(id);f.ver={by:me().name.split(' (')[0],at:R.NOW.toISOString()};log('Directory verified','Facility '+id);toast('Marked verified now');render()}};
A[a]&&A[a]()});
function setSt(id,s){const r=S.referrals.find(x=>x.id===id);r.status=s;r.ev.push([s,R.NOW.toISOString(),me().name.split(' (')[0]]);log('Status: '+s,'Referral '+id);render()}
function reasonDlg(id,title,list,st){dlg(`<h2>${title}</h2><form id="rs"><div class="field"><label for="rc">Reason (required)</label><select id="rc"><option value="">Choose a reason</option>${list.map(x=>`<option>${x}</option>`).join('')}</select><div id="rce" class="err" role="alert"></div></div><div class="field"><label for="rn">Note (optional, no patient identifiers)</label><textarea id="rn" style="min-height:70px"></textarea></div><div class="chip-row"><button class="btn ${st==='Declined'?'danger':''}">Confirm</button><button type="button" class="btn quiet" data-close>Back</button></div></form>`,d=>{$('#rs',d).onsubmit=ev=>{ev.preventDefault();const v=$('#rc',d).value;if(!v){$('#rce',d).textContent='A reason is required so the loop can be closed.';return $('#rc',d).focus()}const r=S.referrals.find(x=>x.id===id);r.reasonCode=v;r.reasonText=$('#rn',d).value.trim();d.close();setSt(id,st);toast(st+' with reason recorded')}})}
function timeoutDlg(){let n=60;const d=dlg(`<h2>Still there?</h2><p>For patient privacy you will be signed out in <b id="cd">60</b> seconds. Unsent drafts stay encrypted on this device.</p><div class="chip-row"><button class="btn" data-close>Stay signed in</button><button class="btn quiet" id="so">Sign out now</button></div>`);const iv=setInterval(()=>{n--;const c=$('#cd',d);if(c)c.textContent=n;if(n<=0||!d.isConnected){clearInterval(iv);if(n<=0){d.close();stopSession('You were signed out after a period of inactivity.')}}},1000);$('#so',d).onclick=()=>{clearInterval(iv);d.close();stopSession('You have been signed out.')};d.addEventListener('close',()=>clearInterval(iv))}
setInterval(()=>{if(S.user){S.sessionLeft=Math.max(0,S.sessionLeft-60)}},60000);
setInterval(()=>{const t=$('#elapsed');if(t&&S.wiz){const el=Math.round((Date.now()-S.wiz.start)/1000);t.textContent=Math.floor(el/60)+':'+String(el%60).padStart(2,'0')}},1000);
window.RFState=S;render();
})();
